def parse_args():

    class ActionN1(argparse.Action):

        def __init__(self, option_strings, dest, nargs=None, **kwargs):
            super().__init__(option_strings, dest, nargs=argparse.OPTIONAL, **kwargs)

        def __call__(self, parser, namespace, values, option_string=None):
            values = True
            setattr(namespace, self.dest, values)

    parser = argparse.ArgumentParser(description="Auto config generator")
    parser.add_argument('-i', '--bts_id', type=str, required=False, default='',
                        help="eg. enb1=1:enb2=2")
    parser.add_argument('-b', '--build', required=False,
                        help="eg. SBTS21B_2104_001_0.0")
    parser.add_argument('-t', '--type', required=False,
                        help="eg. FSM4")
    parser.add_argument('-p', '--profile', required=False, default="CLOUD_R4A_CUS",
                        help="eg. CLOUD_R4A_CUS")
    parser.add_argument('-l', '--log_path', required=False, default='/home/ute',
                        help="eg. /home/ute/testline_init_results/logs")
    parser.add_argument('-o', '--output_dir', required=False, default='/home/ute/config',
                        help="Output directory with generated files")
    parser.add_argument('-n1', '--release_n1', required=False, default=False, action=ActionN1,
                        help="Generate scfc file for release n-1")
    parser.add_argument('-v', '--vlan_id', required=False, default='',
                        help="Vlan_id for all enb's")
    parser.add_argument('-c', '--custom_dir', required=False, default='',
                        help="Path to directory with custom yaml profiles")
    parser.add_argument('-y', '--yaml_map', required=False, default='',
                        help="Specify yamls which needs to be substituted in profile configuration, e.g. env=env.yaml")
    parser.add_argument('--perf', required=False, default=False, action='store_true',
                        help="Optimize configuration to boost performance instead of debugging")
    parser.add_argument('-rk', '--root_key', required=False, default='',
                        help="Public root key for ssh login")
    parser.add_argument('-sk', '--service_key', required=False, default='',
                        help="Public service key for ssh login")
    args = parser.parse_args()
    return args


def get_version():
    try:
        ac_version = version("auto_config")
    except Exception:
        ac_version = "Unknown"
    return ac_version


def generate_config(enb_id='', build=None, device_type='FSM4', profile='CLOUD_R4A_CUS',
                    log_path='/home/ute/config', output_dir='/home/ute/config', release_n1=False,
                    vlan_id='', custom_dir='', yaml_map='', is_perf=False, root_key='', service_key=''):

    try:
        setup_logger(log_path)
        lib_version = get_version()
        logger.info(f"{'-'*12} CONFIG GENERATOR {lib_version} {'-'*12}")

        # install emssim if missing
        check_install_emssim()

        #############################################################################
        # SCFC for golden release
        # prepare config structures, parse BUILD, parse PDDB and generate golden SCFC
        (execution_config, enb_config, ue_config, env_config, epc_config, hw_config, build_translator) = generate_scfc(
            enb_id=enb_id, build=build, device_type=device_type, profile=profile,
            output_dir=output_dir,
            vlan_id=vlan_id, custom_dir=custom_dir, yaml_map=yaml_map, is_perf=is_perf, root_key=root_key, service_key=service_key)

        # dump env_config
        save_yaml_file(output_dir, 'env.yaml', env_config)

        #############################################################################
        # TextBased ConfigFiles - CUS.ini, EPC.lua, UE.db
        logger.info("-" * 48)
        if not custom_dir or 'ue.yaml' in yaml_map:
            for generator in (CUS, EPC, UEDB, COCO):
                generator().to_file(output_dir=output_dir,
                                    execution_config=execution_config,
                                    ue_config=ue_config,
                                    enb_config=enb_config,
                                    env_config=env_config,
                                    epc_config=epc_config,
                                    hw_config=hw_config)

        #############################################################################
        # SCFC for release n-1
        if release_n1:
            logger.info("-" * 48)
            logger.info("Generating SCFC files for release n-1")
            build_translator.set_rel_n1()

            generate_scfc(
                enb_id=enb_id, build=os.path.basename(build_translator.pddb_filename_n1), device_type=device_type, profile=profile,
                output_dir=output_dir,
                vlan_id=vlan_id, custom_dir=custom_dir, yaml_map=yaml_map, is_perf=is_perf, root_key=root_key, service_key=service_key,
                for_n1=True)

        tl_update("generate_config", 1, {"status": "success"})
        logger.info('-' * 48)
        return True
    except Exception as exc:
        tl_update("generate_config", 1, {"status": "failure", "exception": f"{exc}"})
        logger.exception(exc, exc_info=True)
        raise


def generate_scfc(enb_id='', build=None, device_type='FSM4', profile='CLOUD_R4A_CUS',
                  output_dir='/home/ute/config',
                  vlan_id='', custom_dir='', yaml_map='', is_perf=False, root_key='', service_key='', for_n1=False):

    # prepare output dir
    logger.info(f"Preparing output directory in {output_dir}")
    output_dir = Path(output_dir)
    output_dir.mkdir(parents=True, exist_ok=True)

    # set environment configuration
    execution_config = get_execution_config(build, is_perf, device_type, profile, vlan_id, root_key, service_key)

    # load source files
    source_files = load_source_files(profile, custom_dir, yaml_map)

    # prepare config files
    enb_config = Config.get_config(source_files['enb'], enb_id, source_files['rmods'], source_files['bbmods_smods'])
    ue_config = get_ue_config(source_files['ue'], source_files['uecap_config'], source_files['uecap_ini'])
    env_config = get_env_config(source_files['env'], enb_config)
    epc_config = source_files['epc']
    hw_config = source_files['hw']

    # set duplex mode; specific for build
    execution_config['duplex_mode'] = get_duplex_mode(enb_config, build)

    # get pddb_build and release
    bt = BuildTranslator(build=build)
    execution_config['release'] = float(bt.pddb_release_number)
    execution_config['pddb_release'] = bt.pddb_release

    # # parse pddb file into python dictionary
    pddb_parser = PddbParser()
    pddb_parser.parse_pddb_file(filepath=bt.pddb_file_path)

    for k, enb_config_values in enb_config.items():
        if 'custom_params' in enb_config_values:
            validate_custom_params_correctness(enb_config_values['custom_params'], pddb_parser.parsed_pddb['PDDB'])

        if 'tnl_conf' in enb_config_values:
            validate_custom_tnl_pattern_correctnes(enb_config_values)
            if is_type_sa(enb_config_values):
                setup_type = 'SA'
                intefaces_list = ['f1c', 'xnc', 'ngc', 'f1u', 'xnu', 'ngu']
                validate_provided_interfaces(intefaces_list, enb_config_values, setup_type)
            if is_type_sa_nsa(enb_config_values):
                setup_type = 'SA+NSA'
                intefaces_list = ['f1c', 'xnc', 'x2c', 'ngc', 'f1u', 'xnu', 'x2u', 'ngu', 's1u']
                validate_provided_interfaces(intefaces_list, enb_config_values, setup_type)

    #############################################################################
    # Generate SCFC
    BTSFactory(for_n1=for_n1).to_file(
        output_dir=output_dir,
        execution_config=execution_config,
        ue_config=ue_config,
        enb_config=enb_config,
        env_config=env_config,
        epc_config=epc_config,
        hw_config=hw_config,
        pddb_release=bt.pddb_release,
        pddb_parser=pddb_parser,
    )
    return execution_config, enb_config, ue_config, env_config, epc_config, hw_config, bt


def generate_cus_ini_epc_lua(enb_id='', build=None, device_type='FSM4', profile='CLOUD_R4A_CUS',
                             output_dir='/home/ute/config', vlan_id='', custom_dir='', yaml_map='', is_perf=False,
                             root_key='', service_key='', profile_path=None):

    try:
        setup_logger('/home/ute/config')
        lib_version = get_version()
        logger.info(f"{'-'*12} CONFIG GENERATOR {lib_version} {'-'*12}")

        # install emssim if missing
        check_install_emssim()
        # prepare output dir
        logger.info(f"Preparing output directory in {output_dir}")
        output_dir = Path(output_dir)
        output_dir.mkdir(parents=True, exist_ok=True)

        # set environment configuration
        execution_config = get_execution_config(build, is_perf, device_type, profile, vlan_id, root_key, service_key)

        # load source files
        source_files = load_source_files(profile, custom_dir, yaml_map, profile_path)

        # prepare config files
        enb_config = Config.get_config(source_files['enb'], enb_id, source_files['rmods'], source_files['bbmods_smods'])
        ue_config = get_ue_config(source_files['ue'], source_files['uecap_config'], source_files['uecap_ini'])
        epc_config = source_files['epc']
        hw_config = source_files['hw']
        execution_config['duplex_mode'] = get_duplex_mode(enb_config, build)

        # get pddb_build and release
        bt = BuildTranslator(build=build)
        execution_config['release'] = float(bt.pddb_release_number)

        # set duplex mode; specific for build
        execution_config['duplex_mode'] = get_duplex_mode(enb_config, build)
        CUS().to_file(output_dir=output_dir,
                      execution_config=execution_config,
                      ue_config=ue_config,
                      enb_config=enb_config,
                      epc_config=epc_config,
                      hw_config=hw_config)
        CUS_SCN().to_file(output_dir=output_dir,
                          execution_config=execution_config,
                          ue_config=ue_config,
                          enb_config=enb_config,
                          epc_config=epc_config,
                          hw_config=hw_config)
        EPC().to_file(output_dir=output_dir,
                      execution_config=execution_config,
                      ue_config=ue_config,
                      enb_config=enb_config,
                      epc_config=epc_config,
                      hw_config=hw_config)
    except Exception as exc:
        tl_update("generate_config", 1, {"status": "failure", "exception": f"{exc}"})
        logger.exception(exc, exc_info=True)
        raise
